def regex_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)

    def matches(ch: str, pat: str) -> bool:
        return pat == '.' or ch == pat

    # prev corresponds to dp[i+1][*]
    prev = [False] * (n + 1)

    for i in range(m, -1, -1):
        cur = [False] * (n + 1)
        # dp[i][n] is true only when i == m (empty pattern matches empty string)
        cur[n] = (i == m)
        # fill DP for pattern positions from right to left
        for j in range(n - 1, -1, -1):
            pat_char = p[j]
            # Check if a quantifier follows the current pattern character
            if j + 1 < n and p[j + 1] in '*+?':
                quant = p[j + 1]
                if quant == '*':
                    # Zero or more: either skip the x* part or consume one char if it matches
                    zero = cur[j + 2]          # skip the x*
                    more = False
                    if i < m and matches(s[i], pat_char):
                        more = prev[j]         # stay at same pattern after consuming one char
                    cur[j] = zero or more
                elif quant == '+':
                    # One or more: need at least one match, then either continue or stop
                    if i < m and matches(s[i], pat_char):
                        cur[j] = prev[j] or prev[j + 2]
                    else:
                        cur[j] = False
                elif quant == '?':
                    # Zero or one
                    zero = cur[j + 2]          # skip the x?
                    one = False
                    if i < m and matches(s[i], pat_char):
                        one = prev[j + 2]      # consume one char and skip the x?
                    cur[j] = zero or one
            else:
                # No quantifier: literal match of one character
                if i < m and matches(s[i], pat_char):
                    cur[j] = prev[j + 1]
                else:
                    cur[j] = False
        prev = cur

    return prev[0]
