from math import gcd

def max_points(points: list[tuple[int, int]]) -> int:
    if not points:
        return 0
    n = len(points)
    if n <= 2:
        return n

    max_count = 0

    for i in range(n):
        slopes = {}
        duplicate = 0
        xi, yi = points[i]
        for j in range(i + 1, n):
            xj, yj = points[j]
            dx = xj - xi
            dy = yj - yi
            if dx == 0 and dy == 0:
                duplicate += 1
                continue
            g = gcd(dx, dy)
            dx //= g
            dy //= g
            # Normalize sign so that opposite vectors map to the same slope
            if dx < 0:
                dx = -dx
                dy = -dy
            elif dx == 0 and dy < 0:
                dy = -dy
            slope = (dx, dy)
            slopes[slope] = slopes.get(slope, 0) + 1

        if slopes:
            best = max(slopes.values()) + duplicate + 1
        else:
            # All remaining points coincide with points[i]
            best = duplicate + 1
        if best > max_count:
            max_count = best

    return max_count
