from collections import defaultdict

def median_sliding_window(nums, k):
    class MedianFinder:
        __slots__ = ('low', 'high', 'delayed', 'low_size', 'high_size')
        def __init__(self):
            self.low = []          # max‑heap (store -value)
            self.high = []         # min‑heap
            self.delayed = defaultdict(int)
            self.low_size = 0
            self.high_size = 0

        def add(self, num):
            if not self.low or num <= -self.low[0]:
                heappush(self.low, -num)
                self.low_size += 1
            else:
                heappush(self.high, num)
                self.high_size += 1

        def remove(self, num):
            if self.low and num <= -self.low[0]:
                self.delayed[-num] += 1
                self.low_size -= 1
            else:
                self.delayed[num] += 1
                self.high_size -= 1

        def _prune(self, heap):
            # heap is either self.low (max) or self.high (min)
            while heap:
                val = -heap[0] if heap is self.low else heap[0]
                if self.delayed.get(val, 0):
                    heappop(heap)
                    self.delayed[val] -= 1
                    if self.delayed[val] == 0:
                        del self.delayed[val]
                else:
                    break

        def _balance(self):
            # keep low_size >= high_size and difference <= 1
            if self.low_size > self.high_size + 1:
                val = -heappop(self.low)
                self.low_size -= 1
                heappush(self.high, val)
                self.high_size += 1
            elif self.low_size < self.high_size:
                val = heappop(self.high)
                self.high_size -= 1
                heappush(self.low, -val)
                self.low_size += 1

        def rebalance(self):
            self._balance()
            self._prune(self.low)
            self._prune(self.high)

        def get_median(self):
            if self.low_size > self.high_size:
                return float(-self.low[0])
            return (-self.low[0] + self.high[0]) / 2.0

    mf = MedianFinder()
    res = []
    n = len(nums)

    # initial window
    for i in range(k):
        mf.add(nums[i])
    mf.rebalance()
    res.append(mf.get_median())

    # slide the window
    for i in range(k, n):
        mf.remove(nums[i - k])
        mf.add(nums[i])
        mf.rebalance()
        res.append(mf.get_median())

    return res
