import heapq
from collections import defaultdict

def alien_order(words: list[str]) -> str:
    # Edge case: empty list
    if not words:
        return ''

    # Collect all distinct letters
    letters = set()
    for w in words:
        letters.update(w)

    # Build graph (adjacency list) and indegree map
    graph = defaultdict(set)   # using set to avoid duplicate edges
    indegree = {c: 0 for c in letters}

    # Derive ordering constraints from consecutive words
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        # If a word is followed by its own proper prefix, ordering is impossible
        if len(w1) > len(w2) and w1.startswith(w2):
            return ''
        # Find first differing character
        for j in range(min(len(w1), len(w2))):
            if w1[j] != w2[j]:
                u, v = w1[j], w2[j]
                if v not in graph[u]:
                    graph[u].add(v)
                    indegree[v] += 1
                break

    # Kahn's algorithm with a min‑heap to obtain the lexicographically smallest order
    heap = [c for c in indegree if indegree[c] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        c = heapq.heappop(heap)
        result.append(c)
        for nxt in graph[c]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    # If we couldn't include every letter, a cycle exists
    if len(result) != len(letters):
        return ''
    return ''.join(result)
