def eval_bool(expr: str, env: dict) -> bool:
    """Evaluate a boolean expression.

    The expression may contain:
    - literals ``true`` and ``false``;
    - identifiers looked up in ``env`` (must be ``bool`` values);
    - the unary operator ``not``;
    - the binary operators ``and`` and ``or``;
    - parentheses for grouping.

    Precedence (high to low): ``not`` > ``and`` > ``or``.
    ``and`` and ``or`` are left‑associative.
    Tokens may be separated by arbitrary whitespace.
    Raises ``KeyError`` if an identifier is not present in ``env``.
    Raises ``SyntaxError`` for malformed expressions.
    ``eval`` / ``exec`` are not used.
    """

    # ----------------------------------------------------------------------
    # Tokeniser
    # ----------------------------------------------------------------------
    def tokenize(s: str):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch.isalpha() or ch == '_':
                j = i
                while j < n and (s[j].isalnum() or s[j] == '_'):
                    j += 1
                word = s[i:j]
                if word == 'true':
                    tokens.append(('TRUE', True))
                elif word == 'false':
                    tokens.append(('FALSE', False))
                elif word == 'not':
                    tokens.append(('NOT', None))
                elif word == 'and':
                    tokens.append(('AND', None))
                elif word == 'or':
                    tokens.append(('OR', None))
                else:
                    tokens.append(('IDENT', word))
                i = j
                continue
            if ch == '(':
                tokens.append(('LPAREN', None))
                i += 1
                continue
            if ch == ')':
                tokens.append(('RPAREN', None))
                i += 1
                continue
            raise SyntaxError(f"Unexpected character {ch!r} in input")
        tokens.append(('EOF', None))
        return tokens

    # ----------------------------------------------------------------------
    # Parser / Evaluator
    # ----------------------------------------------------------------------
    class Parser:
        def __init__(self, tokens, env):
            self.tokens = tokens
            self.pos = 0
            self.env = env

        def peek(self):
            return self.tokens[self.pos]

        def consume(self, expected=None):
            tok = self.peek()
            if expected and tok[0] != expected:
                raise SyntaxError(f"Expected {expected}, got {tok[0]}")
            self.pos += 1
            return tok

        def parse(self):
            value = self.parse_or()
            if self.peek()[0] != 'EOF':
                raise SyntaxError("Unexpected token after expression")
            return value

        # or ::= and ( 'or' and )*
        def parse_or(self):
            left = self.parse_and()
            while self.peek()[0] == 'OR':
                self.consume('OR')
                right = self.parse_and()
                left = left or right
            return left

        # and ::= not ( 'and' not )*
        def parse_and(self):
            left = self.parse_not()
            while self.peek()[0] == 'AND':
                self.consume('AND')
                right = self.parse_not()
                left = left and right
            return left

        # not ::= 'not' not | primary
        def parse_not(self):
            if self.peek()[0] == 'NOT':
                self.consume('NOT')
                operand = self.parse_not()
                return not operand
            return self.parse_primary()

        # primary ::= identifier | true | false | '(' expression ')'
        def parse_primary(self):
            tok = self.peek()
            typ = tok[0]
            if typ == 'TRUE':
                self.consume('TRUE')
                return True
            if typ == 'FALSE':
                self.consume('FALSE')
                return False
            if typ == 'IDENT':
                self.consume('IDENT')
                name = tok[1]
                if name not in self.env:
                    raise KeyError(name)
                return self.env[name]
            if typ == 'LPAREN':
                self.consume('LPAREN')
                value = self.parse_or()
                if self.peek()[0] != 'RPAREN':
                    raise SyntaxError("Expected ')'")
                self.consume('RPAREN')
                return value
            raise SyntaxError(f"Unexpected token {tok}")

    tokens = tokenize(expr)
    parser = Parser(tokens, env)
    return parser.parse()
