from bisect import bisect_left

def lis_length(nums: list[int]) -> int:
    """
    Return the length of the longest strictly increasing subsequence.
    Uses O(n log n) time with a binary‑search tails list.
    """
    tails: list[int] = []          # tails[i] = smallest tail of an inc. subseq of length i+1
    for x in nums:
        idx = bisect_left(tails, x)  # first position with value >= x
        if idx == len(tails):
            tails.append(x)         # we can extend the longest subsequence
        else:
            tails[idx] = x          # improve the tail for length idx+1
    return len(tails)
