def min_window(s: str, t: str) -> str:
    if not t:
        return ''
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    required = len(need)          # number of distinct characters required
    formed = 0                    # how many distinct characters have met their required count
    left = 0
    best_len = len(s) + 1
    best_start = 0
    cur_counts = {}

    for right, ch in enumerate(s):
        # Add character to current window if it's needed
        if ch in need:
            cur_counts[ch] = cur_counts.get(ch, 0) + 1
            if cur_counts[ch] == need[ch]:
                formed += 1

        # Try to shrink the window while it still satisfies the requirement
        while formed == required:
            cur_len = right - left + 1
            if cur_len < best_len:
                best_len = cur_len
                best_start = left

            left_char = s[left]
            # If the left character is not needed, just move left forward
            if need.get(left_char, 0) == 0:
                left += 1
                continue

            # If the count of this needed character is exactly the required amount,
            # removing it would break the condition, so we stop shrinking.
            if cur_counts[left_char] == need[left_char]:
                break

            # Otherwise we have a surplus of this character; remove it.
            cur_counts[left_char] -= 1
            left += 1

    return s[best_start:best_start + best_len] if best_len <= len(s) else ''
