                # tens = 2
                if b == '*':
                    cnt += 6          # units 1‑6
                elif b == '0':
                    cnt += 1
                elif int(b) <= 6:
                    cnt += 1
                two = cnt
            elif a == '1':
                if b == '*':
                    two = 9          # units 1‑9
                elif b == '0':
                    two = 1
                else:
                    two = 1
            elif a == '2':
                if b == '*':
                    two = 6          # units 1‑6
                elif b == '0':
                    two = 1
                elif int(b) <= 6:
