from typing import List, Tuple

def islands_after_adds(rows: int, cols: int, positions: List[Tuple[int, int]]) -> List[int]:
    n = rows * cols
    parent = list(range(n))
    size = [1] * n
    land = [False] * n

    def find(x: int) -> int:
        # iterative path compression
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> bool:
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]
        return True

    islands = 0
    result: List[int] = []
    for r, c in positions:
        idx = r * cols + c
        if not land[idx]:
            land[idx] = True
            islands += 1
            # up
            if r > 0:
                nb = idx - cols
                if land[nb] and union(idx, nb):
                    islands -= 1
            # down
            if r < rows - 1:
                nb = idx + cols
                if land[nb] and union(idx, nb):
                    islands -= 1
            # left
            if c > 0:
                nb = idx - 1
                if land[nb] and union(idx, nb):
                    islands -= 1
            # right
            if c < cols - 1:
                nb = idx + 1
                if land[nb] and union(idx, nb):
                    islands -= 1
        result.append(islands)
    return result
