def alien_order(words: list[str]) -> str:
    if not words:
        return ''
    from collections import defaultdict
    import heapq

    # All distinct characters that appear in the input.
    unique = set()
    for w in words:
        unique.update(w)

    # Graph representation.
    adj = defaultdict(set)          # adjacency list
    indegree = {c: 0 for c in unique}

    # Build constraints from consecutive words.
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        # A longer word that starts with the shorter one is impossible.
        if len(w1) > len(w2) and w1.startswith(w2):
            return ''
        # Find first mismatch to deduce ordering.
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                if c2 not in adj[c1]:
                    adj[c1].add(c2)
                    indegree[c2] += 1
                break
        # If no mismatch, the words are identical up to the shorter length – ok.

    # Kahn's algorithm with a min‑heap to always extract the smallest available letter.
    heap = [c for c, d in indegree.items() if d == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        c = heapq.heappop(heap)
        order.append(c)
        for nb in adj[c]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(heap, nb)

    # If we couldn't place every character, a cycle exists.
    if len(order) != len(unique):
        return ''
    return ''.join(order)
